DROP POLICY "Team members can create preparation" ON "training_session_preparations" CASCADE;--> statement-breakpoint
DROP POLICY "Team members can update preparation" ON "training_session_preparations" CASCADE;--> statement-breakpoint
CREATE POLICY "Facilitators can create preparation" ON "training_session_preparations" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (training_session_id IN (SELECT id FROM training_sessions WHERE team_id IN (SELECT team_id FROM profiles WHERE id = current_profile_id() AND access_removed_at IS NULL)) AND training_session_id IN (SELECT training_session_id FROM training_session_facilitators WHERE profile_id = current_profile_id()));--> statement-breakpoint
CREATE POLICY "Facilitators can update preparation" ON "training_session_preparations" AS PERMISSIVE FOR UPDATE TO "authenticated" USING (training_session_id IN (SELECT id FROM training_sessions WHERE team_id IN (SELECT team_id FROM profiles WHERE id = current_profile_id() AND access_removed_at IS NULL)) AND training_session_id IN (SELECT training_session_id FROM training_session_facilitators WHERE profile_id = current_profile_id())) WITH CHECK (training_session_id IN (SELECT id FROM training_sessions WHERE team_id IN (SELECT team_id FROM profiles WHERE id = current_profile_id() AND access_removed_at IS NULL)) AND training_session_id IN (SELECT training_session_id FROM training_session_facilitators WHERE profile_id = current_profile_id()));